// Production: exec syft {repo}:{tag} -o cyclonedx-json
// syft outputs standard CycloneDX JSON format
// Mock SBOM structure:
const ctx=$input.first().json;
const sbom={
  bomFormat:'CycloneDX',specVersion:'1.4',
  serialNumber:`urn:uuid:${ctx.release_id}`,
  metadata:{component:{name:ctx.repo,version:ctx.tag,type:'application'},
    timestamp:ctx.created_at,tools:[{name:'Syft',version:'0.90.0'}]},
  components:[
    {type:'library',name:'express',version:'4.18.2',purl:'pkg:npm/express@4.18.2'},
    {type:'library',name:'lodash',version:'4.17.21',purl:'pkg:npm/lodash@4.17.21'},
  ]
};
return[{json:{...ctx,sbom,component_count:sbom.components.length}}];

const current=$('Generate SBOM (Syft)').first().json;
const prev_rows=$('Fetch Previous SBOM').all();
const prev_sbom=prev_rows.length>1?JSON.parse(prev_rows[1].json.sbom_json||'{}'):null;
if(!prev_sbom) return[{json:{...current,diff:{added:[],removed:[],changed:[]},is_first_release:true}}];
const prev_pkgs=new Set((prev_sbom.components||[]).map(c=>c.purl));
const curr_pkgs=new Set(current.sbom.components.map(c=>c.purl));
const added=[...curr_pkgs].filter(p=>!prev_pkgs.has(p));
const removed=[...prev_pkgs].filter(p=>!curr_pkgs.has(p));
return[{json:{...current,diff:{added,removed,added_count:added.length,removed_count:removed.length},has_changes:added.length>0||removed.length>0}}];

